//! Curves generated by `ecdb/sage/generate.sage` (JSONL, schema
//! ecdb.generated/v1): census curves over small prime and binary fields,
//! cryptographic-size prime-field curves and their twists, CM curves,
//! pairing-friendly families and random genus-2 Jacobians.
//!
//! Sage computed these values; this importer re-checks every one it can
//! afford before inserting and refuses a record that fails:
//! - the ICV1 model JSON and slug are rebuilt from (field, a, b, #E);
//! - the model is nonsingular and #E lies in the Hasse interval;
//! - the sample point lies on the curve and [N]P = O;
//! - the generator lies on the curve, [r]G = O, r h = N, r passes Miller–Rabin;
//! - the twist order is 2q + 2 - N; t^2 - 4q = f^2 D_K for the CM data;
//! - the embedding degree k is the least k with r | q^k - 1;
//! - genus 2: L(T) has the functional-equation shape and the Weil bounds,
//!   #J = L(1), #C = q + 1 + a_1, and #C is recounted for p < 2^14.

use super::registry::{
    binary_field, class_row, invariant_row, prime_field, FieldSpec, ALIAS_SQL, CLASS_SQL, CURVE_SQL, FIELD_SQL,
    INVARIANT_SQL, LINK_CLASS_SQL, POINT_SQL, SUBGROUP_SQL, ZETA_SQL,
};
use super::siblings::prime_icv1;
use super::{bulk, bulk1, Ctx, Report};
use crate::ec::{is_probable_prime, Curve};
use crate::field::a_invariants;
use crate::math::{icv1_binary_field, sha256_hex, weil_label};
use anyhow::{anyhow, bail, Context, Result};
use num_bigint::BigInt;
use num_integer::Integer;
use num_traits::{One, Signed, ToPrimitive, Zero};
use serde_json::{json, Map, Value};
use std::collections::BTreeMap;
use std::path::Path;

pub const PACK: &str = "generated";
const SCHEMA: &str = "ecdb.generated/v1";
const GENERATOR: &str = "ecdb/sage/generate.sage";

const FROB_SQL: &str = "
INSERT INTO ec.frobenius_genus1 (isogeny_class_id, trace, trace_mod_p, frobenius_discriminant, disc_status,
       cm_discriminant, conductor_v, conductor_bits, class_number, class_number_status, is_anomalous, is_supersingular,
       status, provenance_id)
SELECT ic.id, r.trace, r.trace_mod_p, r.disc, r.disc_status::ec.fact_status, r.d_k, r.f, ec.bits(r.f), r.h_k,
       r.h_status::ec.fact_status, r.anomalous, r.supersingular, 'proved', $2::bigint
FROM jsonb_to_recordset($1::jsonb) AS r(label text, trace numeric, trace_mod_p numeric, disc numeric, disc_status text,
     d_k numeric, f numeric, h_k numeric, h_status text, anomalous boolean, supersingular boolean)
JOIN ec.isogeny_class_fq ic ON ic.label = r.label
ON CONFLICT (isogeny_class_id) DO NOTHING";

