fn int(v: &Value, what: &str) -> Result<BigInt> {
    match v {
        Value::String(s) => s.parse().map_err(|_| anyhow!("{what}: not an integer: {s}")),
        Value::Number(n) => n.to_string().parse().map_err(|_| anyhow!("{what}: not an integer: {n}")),
        _ => bail!("{what} missing"),
    }
}

fn opt_int(v: &Value) -> Option<BigInt> {
    int(v, "").ok()
}

/// Rows of one batch, inserted together.
#[derive(Default)]
struct Batch {
    fields: BTreeMap<String, Value>,
    classes: BTreeMap<String, Value>,
    curves: Vec<Value>,
    invariants: Vec<Value>,
    aliases: Vec<Value>,
    links: Vec<Value>,
    zeta: Vec<Value>,
    points: Vec<Value>,
    subgroups: Vec<Value>,
    frob: Vec<Value>,
    twists: Vec<Value>,
    pairing: Vec<Value>,
    generation: Vec<Value>,
    g2_curves: Vec<Value>,
    g2_classes: BTreeMap<String, Value>,
    g2_links: Vec<Value>,
    g2_invariants: Vec<Value>,
    g2_generation: Vec<Value>,
}

/// One genus-1 record: verify, then append its rows.
fn genus1(rec: &Value, b: &mut Batch, report: &mut Report) -> Result<()> {
    let field = &rec["field"];
    let order = int(&rec["order"], "order")?;
    let kind = field["kind"].as_str().unwrap_or_default();
    let (spec, fid, slug, model_json, sha, model, form): (FieldSpec, String, String, String, String, &str, &str) =
        match kind {
            "prime" => {
                let p = int(&field["p"], "p")?;
                let (prime, _) = is_probable_prime(&p);
                if !prime {
                    bail!("p = {p} is composite");
                }
                let a = int(&rec["a"], "a")?;
                let bb = int(&rec["b"], "b")?;
                let (slug, mj, sha, _) = prime_icv1(&p, &a, &bb, &order)?;
                let fid = format!("fp-{p}");
                (prime_field(&fid, &p)?, fid, slug, mj, sha, "short_weierstrass", "y^2=x^3+a*x+b")
            }
            "binary" => {
                let m = field["m"].as_u64().ok_or_else(|| anyhow!("binary field without m"))?;
                let modulus = field["modulus"].as_str().ok_or_else(|| anyhow!("binary field without modulus"))?;
                let fid = icv1_binary_field(m, modulus);
                let spec = binary_field(&fid, modulus)?;
                let a = spec.fq.format(&spec.fq.parse(rec["a"].as_str().unwrap_or_default())?);
                let bb = spec.fq.format(&spec.fq.parse(rec["b"].as_str().unwrap_or_default())?);
                if spec.fq.is_zero(&spec.fq.parse(&bb)?) {
                    bail!("b = 0: singular");
                }
                let mj = format!(
                    "{{\"a\":\"{a}\",\"b\":\"{bb}\",\"field\":\"{fid}\",\"form\":\"y^2+xy=x^3+a*x^2+b\",\"modulus\":\"{}\",\"v\":\"1\"}}",
                    modulus.to_lowercase()
                );
                let sha = sha256_hex(&mj);
                let t = &spec.q + BigInt::one() - &order;
                let tr = if t.is_negative() { format!("m{}", t.abs()) } else { t.to_string() };
                let slug = format!("icv1-f2m{m}-t{tr}-{}", &sha[..8]);
                (spec, fid, slug, mj, sha, "binary_weierstrass", "y^2+xy=x^3+a*x^2+b")
            }
            other => bail!("unsupported field kind {other:?}"),
        };
    let k = &spec.fq;
    let q = spec.q.clone();
    let t = &q + BigInt::one() - &order;
    let (label, class) = class_row(&spec, &t)?; // also the Hasse check
    let mut coeff = Map::new();
    coeff.insert("a".into(), json!(k.format(&k.parse(rec["a"].as_str().unwrap_or_default())?)));
    coeff.insert("b".into(), json!(k.format(&k.parse(rec["b"].as_str().unwrap_or_default())?)));
    let (a, _) = a_invariants(k, model, &coeff)?;
    let curve = Curve { k, a };
    let point = |v: &Value| -> Result<crate::ec::Point> {
        let xy = v.as_array().filter(|a| a.len() == 2).ok_or_else(|| anyhow!("point is not [x, y]"))?;
        let x = k.parse(xy[0].as_str().unwrap_or_default())?;
        let y = k.parse(xy[1].as_str().unwrap_or_default())?;
        Ok(Some((x, y)))
    };
    let p0 = point(&rec["point"])?;
    if !curve.on_curve(&p0) {
        bail!("sample point is not on the curve");
    }
    if curve.mul(&order, &p0)?.is_some() {
        bail!("[N]P != O for the sample point: N = {order} is not the group order");
    }
    let mut inv = invariant_row(&slug, k, model, &coeff, None)?;
    inv["status"] = json!("proved");

    // subgroup and generator
    let mut subgroup: Option<(BigInt, BigInt, bool)> = None;
    if !rec["generator"].is_null() {
        let g = point(&rec["generator"])?;
        let r = int(&rec["subgroup_order"], "subgroup_order")?;
        let h = int(&rec["cofactor"], "cofactor")?;
        if &r * &h != order {
            bail!("r h = {} != N = {order}", &r * &h);
        }
        if g.is_none() || !curve.on_curve(&g) {
            bail!("generator is not a point of the curve");
        }
        if curve.mul(&r, &g)?.is_some() {
            bail!("[r]G != O");
        }
        let (prime, proved) = is_probable_prime(&r);
        if rec["subgroup_prime"].as_bool() == Some(true) && !prime {
            bail!("r is composite");
        }
        b.points.push(json!({ "key": slug, "coordinates": rec["generator"], "order_value": r.to_string() }));
        let status = if prime && proved {
            "proved"
        } else if prime {
            "probable"
        } else {
            "unknown"
        };
        b.subgroups.push(json!({
            "key": slug, "order_value": r.to_string(), "cofactor": h.to_string(), "coordinates": rec["generator"],
            "uid": null, "is_prime": prime, "primality_status": status, "status": status,
        }));
        subgroup = Some((r, h, prime));
    }

    // embedding degree (verified minimal)
    if let Some((r, _, true)) = &subgroup {
        let k_emb = rec["embedding_degree"].as_u64();
        let lower = rec["embedding_lower_bound"].as_u64();
        let qm = &q % r;
        let mut acc = BigInt::one();
        let limit = k_emb.or(lower.map(|l| l - 1)).unwrap_or(0);
        let mut first = None;
        for i in 1..=limit {
            acc = (&acc * &qm) % r;
            if acc.is_one() {
                first = Some(i);
                break;
            }
        }
        if first != k_emb {
            bail!("embedding degree: the record says {k_emb:?}, ecdb finds {first:?} up to {limit}");
        }
        let family = rec["family"].as_str().unwrap_or_default();
        let fam_name = family.strip_prefix("pairing-").map(|f| f.to_uppercase());
        b.pairing.push(json!({
            "key": slug, "order_value": r.to_string(), "k": k_emb, "k_lower": if k_emb.is_none() { lower } else { None },
            "target_bits": k_emb.map(|kk| kk * q.bits()), "rho": (q.bits() as f64) / (r.bits() as f64),
            "friendly": k_emb.map(|kk| kk <= 50), "family": fam_name,
        }));
    }

    // Frobenius / CM data
    let disc = &t * &t - BigInt::from(4) * &q;
    let cm = &rec["cm"];
    let (mut d_k, mut f, mut h_k) = (opt_int(&cm["D_K"]), opt_int(&cm["f"]), opt_int(&cm["h_K"]));
    if let Some(d) = opt_int(&cm["disc"]) {
        if d != disc {
            bail!("CM disc {d} != t^2 - 4q = {disc}");
        }
    }
    if let (Some(dk), Some(ff)) = (&d_k, &f) {
        if &(ff * ff) * dk != disc {
            report.count("cm_data_dropped_inconsistent", 1);
            (d_k, f, h_k) = (None, None, None);
        }
    }
    let p_char = spec.p.clone();
    if !disc.is_zero() {
        b.frob.push(json!({
            "label": label, "trace": t.to_string(), "trace_mod_p": t.mod_floor(&p_char).to_string(),
            "disc": disc.to_string(), "disc_status": if d_k.is_some() { "proved" } else { "unknown" },
            "d_k": d_k.as_ref().map(|x| x.to_string()), "f": f.as_ref().map(|x| x.to_string()),
            "h_k": h_k.as_ref().map(|x| x.to_string()), "h_status": if h_k.is_some() { "proved" } else { "unknown" },
            "anomalous": (&t - BigInt::one()).mod_floor(&p_char).is_zero() && spec.degree == 1,
            "supersingular": t.mod_floor(&p_char).is_zero(),
        }));
    }

    // twist
    if let Some(tw) = opt_int(&rec["twist_order"]) {
        if tw != BigInt::from(2) * &q + BigInt::from(2) - &order {
            bail!("twist order {tw} != 2q + 2 - N");
        }
        b.twists.push(json!({ "key": slug, "twist_order": tw.to_string() }));
    }

    let family = rec["family"].as_str().unwrap_or("generated");
    b.fields.entry(fid.clone()).or_insert_with(|| spec.row.clone());
    b.classes.entry(label.clone()).or_insert(class);
    let equation = if model == "short_weierstrass" {
        format!("y^2 = x^3 + {}*x + {}", coeff["a"].as_str().unwrap(), coeff["b"].as_str().unwrap())
    } else {
        format!("y^2 + x*y = x^3 + ({})*x^2 + ({})", coeff["a"].as_str().unwrap(), coeff["b"].as_str().unwrap())
    };
    b.curves.push(json!({
        "field": fid, "model": model, "form": form, "coefficients": coeff, "equation": equation, "family": family,
        "model_json": model_json, "model_sha256": sha, "icv1": null, "slug": slug,
        "is_smooth": true, "smoothness_status": "proved",
    }));
    b.invariants.push(inv);
    b.links.push(json!({ "key": slug, "label": label }));
    b.zeta.push(json!({ "key": slug, "point_counts": [order.to_string()] }));
    b.aliases.push(json!({ "key": slug, "namespace": "icv1_slug", "alias": slug, "retired": false }));
    b.generation.push(generation(rec, json!({ "key": slug })));
    Ok(())
}

/// The generation_provenance row: the method in the table's vocabulary, the
/// unit (whose name seeds Sage's RNG) and the generator path.
fn generation(rec: &Value, mut key: Value) -> Value {
    let family = rec["family"].as_str().unwrap_or_default();
    let method = if family.starts_with("pairing-") {
        "pairing_family"
    } else if family == "crypto-cm" {
        "cm_method"
    } else {
        "seeded_generator"
    };
    let set = rec["set"].as_str().unwrap_or_default();
    let unit = rec["unit"].as_str().unwrap_or_default();
    key["method"] = json!(method);
    key["seed"] = json!(format!("sha256(\"{set}/{unit}\")[:15] as Sage's random seed"));
    key["procedure"] =
        json!(format!("{GENERATOR} {set} units={unit} (Sage {})", rec["sage"].as_str().unwrap_or_default()));
    key["call"] = json!(format!("family {family} params {}", rec["params"]));
    key
}

/// #{(x, y) : y^2 = f(x)} over F_p plus the point at infinity of an odd-degree model.
fn count_g2_points(f: &[BigInt], p: u64) -> u64 {
    let fu: Vec<u64> = f.iter().map(|c| c.mod_floor(&BigInt::from(p)).to_u64().unwrap()).collect();
    let pw = |mut b: u64, mut e: u64| -> u64 {
        let mut r = 1u64;
        b %= p;
        while e > 0 {
            if e & 1 == 1 {
                r = ((r as u128 * b as u128) % p as u128) as u64;
            }
            b = ((b as u128 * b as u128) % p as u128) as u64;
            e >>= 1;
        }
        r
    };
    let mut n = 1u64; // infinity
    for x in 0..p {
        let mut v = 0u64;
        for c in fu.iter().rev() {
            v = ((v as u128 * x as u128 + *c as u128) % p as u128) as u64;
        }
        n += if v == 0 {
            1
        } else if pw(v, (p - 1) / 2) == 1 {
            2
        } else {
            0
        };
    }
    n
}

fn genus2(rec: &Value, b: &mut Batch, report: &mut Report) -> Result<()> {
    let p = int(&rec["field"]["p"], "p")?;
    let (prime, _) = is_probable_prime(&p);
    if !prime || p < BigInt::from(5) {
        bail!("p = {p} is not an odd prime > 3");
    }
    let f: Vec<BigInt> = rec["f"]
        .as_array()
        .ok_or_else(|| anyhow!("no f"))?
        .iter()
        .map(|c| int(c, "f coefficient").map(|v| v.mod_floor(&p)))
        .collect::<Result<_>>()?;
    if f.len() != 6 || !f[5].is_one() {
        bail!("f is not a monic quintic");
    }
    let l: Vec<BigInt> = rec["l_poly"]
        .as_array()
        .ok_or_else(|| anyhow!("no l_poly"))?
        .iter()
        .map(|c| int(c, "L coefficient"))
        .collect::<Result<_>>()?;
    if l.len() != 5 || !l[0].is_one() || l[4] != &p * &p || l[3] != &p * &l[1] {
        bail!("L(T) does not have the shape 1 + a1 T + a2 T^2 + p a1 T^3 + p^2 T^4");
    }
    if &l[1] * &l[1] > BigInt::from(16) * &p || l[2].abs() > BigInt::from(6) * &p {
        bail!("L(T) violates the Weil bounds");
    }
    let jac: BigInt = l.iter().sum();
    if int(&rec["jacobian_order"], "jacobian_order")? != jac {
        bail!("#J != L(1)");
    }
    let npts = &p + BigInt::one() + &l[1];
    if int(&rec["curve_points"], "curve_points")? != npts {
        bail!("#C != p + 1 + a1");
    }
    if p < BigInt::from(1u64 << 14) {
        let counted = count_g2_points(&f, p.to_u64().unwrap());
        if BigInt::from(counted) != npts {
            bail!("#C(F_p) counted {counted}, L(T) implies {npts}");
        }
        report.count("genus2_point_counts_recounted", 1);
    }
    let fid = format!("fp-{p}");
    let spec = prime_field(&fid, &p)?;
    let label = weil_label(2, &p, &l)?;
    let coefficients = json!({
        "f": f.iter().map(|c| c.to_string()).collect::<Vec<_>>(), "h": Vec::<String>::new(),
    });
    let terms: Vec<String> = f
        .iter()
        .enumerate()
        .rev()
        .filter(|(_, c)| !c.is_zero())
        .map(|(i, c)| match i {
            0 => c.to_string(),
            1 => format!("{c}*x"),
            _ => format!("{c}*x^{i}"),
        })
        .collect();
    let equation = format!("y^2 = {}", terms.join(" + "));
    b.fields.entry(fid.clone()).or_insert_with(|| spec.row.clone());
    b.g2_classes.entry(label.clone()).or_insert_with(|| {
        json!({
            "p": p.to_string(), "l_polynomial": l.iter().map(|c| c.to_string()).collect::<Vec<_>>(), "label": label,
            "order_value": jac.to_string(), "curve_points": npts.to_string(),
            "ordinary": !(l[2].mod_floor(&p)).is_zero(),
        })
    });
    let family = rec["family"].as_str().unwrap_or("genus2");
    b.g2_curves.push(json!({ "field": fid, "coefficients": coefficients, "equation": equation, "family": family }));
    b.g2_links.push(json!({ "field": fid, "coefficients": coefficients, "label": label }));
    b.g2_invariants.push(json!({ "field": fid, "coefficients": coefficients, "values": rec["igusa_clebsch"] }));
    b.g2_generation.push(generation(rec, json!({ "field": fid, "coefficients": coefficients })));
    Ok(())
}

async fn flush(ctx: &Ctx<'_>, b: Batch, prov: i64, report: &mut Report) -> Result<()> {
    let c = ctx.client;
    let fields: Vec<Value> = b.fields.into_values().collect();
    report.count("fields", bulk(c, FIELD_SQL, &fields, prov).await?);
    let classes: Vec<Value> = b.classes.into_values().collect();
    report.count("isogeny_classes", bulk(c, CLASS_SQL, &classes, prov).await?);
    report.count("curves", bulk(c, CURVE_SQL, &b.curves, prov).await?);
    report.count("genus1_invariants", bulk(c, INVARIANT_SQL, &b.invariants, prov).await?);
    bulk1(c, ALIAS_SQL, &b.aliases).await?;
    report.count("jacobians_linked", bulk1(c, LINK_CLASS_SQL, &b.links).await?);
    report.count("zeta", bulk(c, ZETA_SQL, &b.zeta, prov).await?);
    report.count("generators", bulk(c, POINT_SQL, &b.points, prov).await?);
    report.count("subgroups", bulk(c, SUBGROUP_SQL, &b.subgroups, prov).await?);
    report.count("frobenius", bulk(c, FROB_SQL, &b.frob, prov).await?);
    report.count("twists", bulk(c, TWIST_SQL, &b.twists, prov).await?);
    report.count("pairing_data", bulk(c, PAIRING_SQL, &b.pairing, prov).await?);
    bulk(c, GENERATION_SQL, &b.generation, prov).await?;
    let g2_classes: Vec<Value> = b.g2_classes.into_values().collect();
    report.count("genus2_classes", bulk(c, G2_CLASS_SQL, &g2_classes, prov).await?);
    report.count("genus2_curves", bulk(c, G2_CURVE_SQL, &b.g2_curves, prov).await?);
    bulk(c, G2_MODEL_SQL, &b.g2_curves, prov).await?;
    report.count("genus2_jacobians_linked", bulk1(c, G2_LINK_SQL, &b.g2_links).await?);
    report.count("genus2_igusa_clebsch", bulk(c, G2_INVARIANT_SQL, &b.g2_invariants, prov).await?);
    bulk(c, G2_GENERATION_SQL, &b.g2_generation, prov).await?;
    Ok(())
}

/// Import JSONL bytes (one generator unit, or a chunk of a pack). `label` names
/// the input in the source row; its SHA-256 is that of `bytes`.
pub async fn import_bytes(ctx: &Ctx<'_>, label: &str, bytes: &[u8], report: &mut Report) -> Result<()> {
    let sha = hex::encode(<sha2::Sha256 as sha2::Digest>::digest(bytes));
    let src = ctx.source(label, &sha, "Sage-generated curves (ecdb/sage/generate.sage)").await?;
    let prov = ctx
        .provenance(
            src,
            "SageMath computation, re-verified by ecdb (ICV1, Hasse, [N]P = O, [r]G = O, Miller-Rabin)",
            None,
        )
        .await?;
    let mut batch = Batch::default();
    let mut n = 0usize;
    for (i, line) in bytes.split(|&c| c == b'\n').filter(|l| !l.is_empty()).enumerate() {
        let rec: Value = match serde_json::from_slice(line) {
            Ok(v) => v,
            Err(e) => {
                report.problem(format!("{label}:{}: not JSON: {e}", i + 1));
                continue;
            }
        };
        if rec["schema"].as_str() != Some(SCHEMA) {
            report.problem(format!("{label}:{}: schema is not {SCHEMA}", i + 1));
            continue;
        }
        let res = match rec["genus"].as_u64() {
            Some(1) => genus1(&rec, &mut batch, report),
            Some(2) => genus2(&rec, &mut batch, report),
            _ => Err(anyhow!("unsupported genus")),
        };
        match res {
            Ok(()) => {
                report.count("records_verified", 1);
                n += 1;
            }
            Err(e) => {
                report.count("records_refused", 1);
                report.problem(format!("{label}:{} ({}): {e}", i + 1, rec["unit"].as_str().unwrap_or_default()));
            }
        }
        if n >= 2000 {
            flush(ctx, std::mem::take(&mut batch), prov, report).await?;
            n = 0;
        }
    }
    flush(ctx, batch, prov, report).await
}

/// Import generator output files (`*.jsonl` or `*.jsonl.gz`) or directories of them.
pub async fn import_paths(ctx: &Ctx<'_>, paths: &[String]) -> Result<Report> {
    let mut report = Report { input: format!("{GENERATOR} output"), ..Default::default() };
    let mut files = Vec::new();
    for p in paths {
        collect_files(Path::new(p), &mut files)?;
    }
    files.sort();
    for f in files {
        let bytes = super::read_bytes(&f).with_context(|| f.display().to_string())?;
        let label = format!("{GENERATOR}#{}", f.display());
        import_bytes(ctx, &label, &bytes, &mut report).await?;
        report.count("files", 1);
    }
    Ok(report)
}

fn collect_files(p: &Path, out: &mut Vec<std::path::PathBuf>) -> Result<()> {
    if p.is_dir() {
        for e in std::fs::read_dir(p)?.flatten() {
            collect_files(&e.path(), out)?;
        }
    } else {
        let name = p.file_name().and_then(|n| n.to_str()).unwrap_or_default();
        if name.ends_with(".jsonl") || name.ends_with(".jsonl.gz") {
            out.push(p.to_path_buf());
        }
    }
    Ok(())
}

/// One gzipped pack part sent to the admin Lambda (`import_pack`, name `generated`).
pub async fn import_part(ctx: &Ctx<'_>, gz: &[u8]) -> Result<Report> {
    let mut bytes = Vec::new();
    std::io::Read::read_to_end(&mut flate2::read::GzDecoder::new(gz), &mut bytes)?;
    let sha = hex::encode(<sha2::Sha256 as sha2::Digest>::digest(&bytes));
    let mut report = Report { input: format!("{GENERATOR} pack part"), sha256: sha.clone(), ..Default::default() };
    import_bytes(ctx, &format!("{GENERATOR}#part-{}", &sha[..16]), &bytes, &mut report).await?;
    Ok(report)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn g2_point_count_matches_a_known_curve() {
        // y^2 = x^5 + 1 over F_7: x^5 + 1 takes values; count by brute force.
        let f: Vec<BigInt> = [1, 0, 0, 0, 0, 1].iter().map(|&c| BigInt::from(c)).collect();
        let mut brute = 1u64;
        for x in 0..7u64 {
            let v = (x.pow(5) + 1) % 7;
            for y in 0..7u64 {
                if (y * y) % 7 == v {
                    brute += 1;
                }
            }
        }
        assert_eq!(count_g2_points(&f, 7), brute);
    }

    #[test]
    fn miller_rabin() {
        assert_eq!(is_probable_prime(&BigInt::from(1_000_003)), (true, true));
        // every prime below 1000 (the census fields), including the extra bases 53..83
        let sieve: Vec<u32> =
            (2..1000u32).filter(|n| (2..*n).take_while(|d| d * d <= *n).all(|d| n % d != 0)).collect();
        for n in 2..1000u32 {
            assert_eq!(is_probable_prime(&BigInt::from(n)).0, sieve.contains(&n), "n = {n}");
        }
        assert!(!is_probable_prime(&BigInt::from(3_215_031_751u64)).0); // strong pseudoprime to 2, 3, 5, 7
        let p256: BigInt =
            "115792089210356248762697446949407573530086143415290314195533631308867097853951".parse().unwrap();
        assert_eq!(is_probable_prime(&p256), (true, false));
    }
}
